import threading, time

def run(atomic):
    stock = {"n": 100}; won = []; lock = threading.Lock()
    def try_win(u):
        if atomic:
            with lock:
                if stock["n"] > 0:
                    stock["n"] -= 1; won.append(u)
        else:
            if stock["n"] > 0:
                time.sleep(0.001)  # 확인과 차감 사이의 틈
                stock["n"] -= 1; won.append(u)
    ts = [threading.Thread(target=try_win, args=(u,)) for u in range(300)]
    for t in ts: t.start()
    for t in ts: t.join()
    return len(won), stock["n"]

print("확인 후 차감 (당첨 수, 남은 수량):", run(False))
print("원자적 차감 (당첨 수, 남은 수량):", run(True))

# 출력 (한 번 돌린 것)
# 확인 후 차감 (당첨 수, 남은 수량): (112, -12)
# 원자적 차감 (당첨 수, 남은 수량): (100, 0)
